import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"1981年 · 收购哲学与价值陷阱","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1981年.md","filePath":"05_quotes/by-year/1981年.md"}'),l={name:"05_quotes/by-year/1981年.md"};function c(u,e,p,s,_,q){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_1981年-·-收购哲学与价值陷阱" tabindex="-1">1981年 · 收购哲学与价值陷阱 <a class="header-anchor" href="#_1981年-·-收购哲学与价值陷阱" aria-label="Permalink to &quot;1981年 · 收购哲学与价值陷阱&quot;">​</a></h1><blockquote><p>我们收购决策目标是最大化真实经济利益，不是最大化管理版图，也不是为了会计报告数字。长期来看，管理层强调会计表象超过经济实质，通常两者都拿不到多少。——巴菲特（51岁）</p></blockquote><p>本页收录1981年致股东信中的经典语录。这一年巴菲特把收购哲学讲得淋漓尽致，点破很多企业收购的通病。同时在高利率背景下第一次清晰推导：高通胀+高利率下，平均股权对个人投资者没有&quot;增值&quot;。ROE为15.2%。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>我们收购决策目标是最大化真实经济利益，不是最大化管理版图，也不是为了会计报告数字。长期来看，管理层强调会计表象超过经济实质，通常两者都拿不到多少。</p></blockquote><blockquote><p>我们宁愿按X价格买优秀企业10%的股权，也不愿按2X价格买它的100%。大多数企业经理偏好正好反过来，而且他们这种行为从来不缺现成理由。</p></blockquote><blockquote><p>我们看过很多吻，很少奇迹。尽管如此，很多管理公主依然对未来吻的潜力保持平静自信——哪怕她们企业后院已经齐膝深，都是没反应的蟾蜍。</p></blockquote><blockquote><p>一类公司，不管有意还是无意，只买特别适应通胀环境的企业。这种受青睐企业必须有两个特征：(1)能轻松涨价，不担心丢失市场份额；(2)能容纳业务大额美元增长，只需要很少额外资本投入。</p></blockquote><blockquote><p>你的董事长不属于第二类。尽管我们对第一类需要集中的经济因素理解还不错，我们实际收购活动在这一块断断续续，做得不够。我们讲道比行道好。</p></blockquote><blockquote><p>1981年末被动投资已经到这个利率水平，典型美国企业对个人所有者来说，已经不值100美分兑1美元了。</p></blockquote><blockquote><p>因为通胀就像一个巨大的企业绦虫。这条绦虫预先就每天吃掉它必需的投资美元，不管宿主健康如何。不管报告盈利水平是什么（哪怕零），企业需要不断更多美元投到应收、存货、固定资产。</p></blockquote><blockquote><p>低回报公司没法分红，这个无能常常被伪装。美国企业越来越多转向股息再投资计划，有时候甚至还有折扣安排，几乎逼着股东再投资。</p></blockquote><blockquote><p>我们推出允许股东指定慈善捐赠接受方的新项目，得到了 extraordinary 热情回应。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1981年ROE为15.2%。巴菲特在信中彻底阐明了自己的收购哲学：大多数收购失败不是因为执行不好，而是因为买贵了、买了烂生意；同时推导出一个残酷结论：高利率+高通胀下，普通股权对个人投资者没有增值价值。同时推出股东指定捐赠项目，获得95.6%的参与率。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1981年/翻译.html">01_letters/1981年/翻译</a> · <a href="/01_letters/1981年/核心总结.html">01_letters/1981年/核心总结</a> · <a href="/01_letters/1981年/思维导图.html">01_letters/1981年/思维导图</a></p>',20)])])}const n=t(l,[["render",c]]);export{h as __pageData,n as default};
